import { MeshBasicNodeMaterial } from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;
  const root = new Group();
  const disposables = [];
  const timelines = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const gradientStops = visualSpec.gradientStops ?? [
    colors.surface,
    colors.ink,
    '#24242d'
  ];

  const makeBasicMaterial = (color, options = {}) => {
    const material = new MeshBasicNodeMaterial({
      color,
      ...options
    });
    disposables.push(material);
    return material;
  };

  const backdropMaterial = makeBasicMaterial(colors.surface);
  const start = gradientStops[0] ?? colors.surface;
  const middle = gradientStops[Math.floor(gradientStops.length / 2)] ?? colors.ink;
  const end = gradientStops[gradientStops.length - 1] ?? colors.ink;

  const hexToVec3 = (hex) => {
    const value = typeof hex === 'string'
      ? Number.parseInt(hex.replace('#', ''), 16)
      : 0x0b0b10;
    return vec3(
      ((value >> 16) & 255) / 255,
      ((value >> 8) & 255) / 255,
      (value & 255) / 255
    );
  };

  backdropMaterial.colorNode = mix(
    mix(hexToVec3(start), hexToVec3(middle), uv().y.mul(2.0).clamp()),
    hexToVec3(end),
    uv().y.mul(2.0).sub(1.0).clamp()
  );

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdropGeometry);

  const row = new Group();
  row.position.set(0, 0, 0.15);
  root.add(row);

  const rowGeometry = new BoxGeometry(5.9, 0.76, 0.075);
  const rowMaterial = makeBasicMaterial(colors.ink);
  const rowMesh = new Mesh(rowGeometry, rowMaterial);
  row.add(rowMesh);
  disposables.push(rowGeometry);

  const imageUrl = config.imageUrl ?? visualSpec.imageUrl;
  let loadedTexture = null;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) return;
      loadedTexture = texture;
      rowMaterial.map = texture;
      rowMaterial.color.set(colors.paper);
      rowMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const insetGeometry = new PlaneGeometry(5.72, 0.58);
  const insetMaterial = makeBasicMaterial(colors.surface, { transparent: true, opacity: 0.82 });
  const inset = new Mesh(insetGeometry, insetMaterial);
  inset.position.z = 0.041;
  row.add(inset);
  disposables.push(insetGeometry);

  const dividerGeometry = new PlaneGeometry(5.35, 0.012);
  const dividerMaterial = makeBasicMaterial(colors.paper, {
    transparent: true,
    opacity: 0.24
  });
  const divider = new Mesh(dividerGeometry, dividerMaterial);
  divider.position.set(0, -0.24, 0.052);
  row.add(divider);
  disposables.push(dividerGeometry);

  const accentGeometry = new PlaneGeometry(0.035, 0.58);
  const accentMaterial = makeBasicMaterial(colors.accent, {
    transparent: true,
    opacity: 0.92
  });
  const accentEdge = new Mesh(accentGeometry, accentMaterial);
  accentEdge.position.set(-2.82, 0, 0.055);
  accentEdge.scale.x = 0.35;
  row.add(accentEdge);
  disposables.push(accentGeometry);

  const textGroup = new Group();
  textGroup.position.set(-2.52, 0, 0.065);
  row.add(textGroup);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  for (const item of items) {
    const content = String(item?.text ?? '');
    if (!content) continue;

    const role = item?.role ?? 'body';
    const fontSize = item?.typography?.fontSize ??
      (role === 'title' || role === 'headline' ? 0.34 : 0.13);

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize,
      color: role === 'meta' || role === 'caption' ? colors.paper : colors.paper,
      align: 'left',
      letterSpacingPx: role === 'label' || role === 'caption' ? 3 : 0
    });

    textObject.position.y = role === 'meta' || role === 'caption' ? -0.12 : 0.08;
    textGroup.add(textObject);
  }

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    row.position,
    { y: 0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  entrance.fromTo(
    row.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '<'
  );
  entrance.play();
  timelines.push(entrance);

  const hoverIn = () => {
    if (disposed) return;
    gsap.to(row.position, {
      y: 0.15,
      duration: 0.35,
      ease: 'power3.out',
      overwrite: true
    });
    gsap.to(accentEdge.scale, {
      x: 1,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true
    });
  };

  const hoverOut = () => {
    if (disposed) return;
    gsap.to(row.position, {
      y: 0,
      duration: 0.35,
      ease: 'power3.out',
      overwrite: true
    });
    gsap.to(accentEdge.scale, {
      x: 0.35,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true
    });
  };

  const press = () => {
    if (disposed) return;
    gsap.timeline()
      .to(row.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'power2.out'
      })
      .to(row.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.28,
        ease: 'back.out(2)'
      });
    ctx.emit('hub-collection.select', {
      node: config.id ?? config.nodeId ?? 'hub-collection-row'
    });
  };

  const focus = () => {
    if (disposed) return;
    gsap.to(accentEdge.scale, {
      x: 1,
      duration: 0.25,
      ease: 'power2.out',
      overwrite: true
    });
  };

  const blur = () => {
    if (disposed) return;
    gsap.to(accentEdge.scale, {
      x: 0.35,
      duration: 0.25,
      ease: 'power2.out',
      overwrite: true
    });
  };

  root.userData.handlers = {
    hover: hoverIn,
    pointerenter: hoverIn,
    pointerleave: hoverOut,
    click: press,
    focus,
    blur
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) timeline.kill();
    gsap.killTweensOf(row);
    gsap.killTweensOf(row.position);
    gsap.killTweensOf(row.scale);
    gsap.killTweensOf(accentEdge.scale);

    for (const resource of disposables) {
      if (resource?.dispose) resource.dispose();
    }

    if (loadedTexture?.dispose) loadedTexture.dispose();
    root.clear();
  };

  return root;
}
